import React from 'react'

const Social = () => {
  return (
    <div className="home-social">
      <a href="" className="home-social-icon" target='_blank'><i className="uil uil-linkedin-alt"></i></a>
      <a href="" className="home-social-icon" target='_blank'><i className="uil uil-github-alt"></i></a>
      <a href="" className="home-social-icon" target='_blank'><i className="uil uil-instagram"></i></a>
      <a href="" className="home-social-icon" target='_blank'><i className="uil uil-facebook"></i></a>
    </div>
  )
}

export default Social
